<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $member = $args['member']; $shared = isset( $args['shared_interests'] ) ? absint( $args['shared_interests'] ) : 0; ?><article class="sd-member-card"><a class="sd-member-card-avatar" href="<?php echo esc_url( sd_get_member_url( $member->ID ) ); ?>"><img src="<?php echo esc_url( sd_avatar( $member->ID, 96 ) ); ?>" alt="<?php echo esc_attr( sd_member_display_name( $member->ID ) ); ?>" loading="lazy"></a><h3><a href="<?php echo esc_url( sd_get_member_url( $member->ID ) ); ?>"><?php echo esc_html( sd_member_display_name( $member->ID ) ); ?></a></h3><?php if ( ! empty( $member->description ) ) : ?><p><?php echo esc_html( wp_trim_words( $member->description, 18 ) ); ?></p><?php endif; ?><?php if ( $shared ) : ?><span class="sd-member-shared"><?php echo esc_html( $shared ); ?> <?php esc_html_e( 'shared interests', 'social-discovery' ); ?></span><?php endif; ?><div class="sd-member-card-actions"><?php get_template_part( 'template-parts/discovery/connection-button', null, array( 'member_id' => $member->ID ) ); ?><a class="sd-button sd-button-primary" href="<?php echo esc_url( sd_get_member_url( $member->ID ) ); ?>"><?php esc_html_e( 'View profile', 'social-discovery' ); ?></a></div></article>
